package piglatin

import (
	"strings"
)

// Sentence translates a sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Split(sentence, " ")
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

func word(w string) string {
	if w == "" {
		return w
	}
	// Rule 1: words that begin with a vowel, or with "xr" or "yt",
	// simply get an "ay" appended.
	if isVowel(w[0]) || strings.HasPrefix(w, "xr") || strings.HasPrefix(w, "yt") {
		return w + "ay"
	}

	// Find the end of the leading consonant cluster. A "y" counts as a
	// vowel once it is no longer the first letter (rule 4).
	i := 0
	for i < len(w) && !isVowel(w[i]) && !(w[i] == 'y' && i > 0) {
		i++
	}

	// Rule 3: if the cluster is followed by "qu", the "u" belongs to
	// the part that is moved to the end.
	if i < len(w) && w[i] == 'q' && i+1 < len(w) && w[i+1] == 'u' {
		i += 2
	}

	return w[i:] + w[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

